import assert from 'node:assert/strict';
import { EventEmitter } from 'node:events';
import { Readable } from 'node:stream';
import { after, test } from 'node:test';
import type { LookupAddress } from 'node:dns';
import dnsPromises from 'node:dns/promises';
import {
    isPublicUnicastAddress, lookupPublicAddresses, openPinnedHttps, readPinnedBody, strictHttpsUrl,
    type PinnedHttpsPolicy, type PinnedHttpsResponse, type PinnedHttpsTransport
} from '../../src/administration/adminPinnedHttps';
import { legacyCatalogArtworkUrl } from '../../src/administration/catalog/adminCatalogArtworkSource';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const address: LookupAddress = { address: '8.8.8.8', family: 4 };
const start = new URL('https://api.example.test/start');
const failure = () => new Error('SYNTHETIC_PINNED_FAILURE');
const policy = (overrides: Partial<PinnedHttpsPolicy> = {}): PinnedHttpsPolicy => ({
    destination: url => strictHttpsUrl(url.href), headers: { Accept: 'application/json', 'User-Agent': 'Finitude/1.0 ( lookup-operator@example.test )' },
    maximumRedirects: 3, failure, ...overrides
});
const response = (statusCode: number, headers: Record<string, string> = {}, body: Buffer | string = ''): PinnedHttpsResponse => ({
    statusCode, headers, rawHeaders: Object.entries(headers).flatMap(entry => entry), body: Readable.from(body.length ? [Buffer.from(body)] : [])
});

test('DNS policy rejects private, CGNAT, link-local, documentation, multicast, ULA, mapped and 6to4 answers', () => {
    for (const ip of ['10.0.0.1', '100.64.0.1', '127.0.0.1', '169.254.169.254', '172.16.0.1', '192.168.0.1', '192.0.2.1',
        '198.51.100.1', '203.0.113.1', '224.0.0.1', '240.0.0.1']) assert.equal(isPublicUnicastAddress({ address: ip, family: 4 }), false, ip);
    for (const ip of ['::1', 'fc00::1', 'fd12::1', 'fe80::1', 'ff02::1', '::ffff:8.8.8.8', '2002:0808:0808::1', '2001:db8::1']) {
        assert.equal(isPublicUnicastAddress({ address: ip, family: 6 }), false, ip);
    }
    assert.equal(isPublicUnicastAddress(address), true);
    assert.equal(isPublicUnicastAddress({ address: '2606:4700:4700::1111', family: 6 }), true);
});

test('one private answer among public ones blocks the request before any connection', async () => {
    let requests = 0;
    for (const answers of [[address, { address: '10.0.0.1', family: 4 }], [{ address: 'fd00::1', family: 6 }, address], [], Array(33).fill(address)]) {
        await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
            lookup: async () => answers, request: async () => { requests++; return response(200); }
        }), /SYNTHETIC_PINNED_FAILURE/);
    }
    assert.equal(requests, 0);
});

test('production transport pins one answer for both lookup forms, verifies TLS and sends exactly three headers', async () => {
    let called = 0;
    const { url, response: opened } = await openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address],
        httpsRequest: ((target: URL, options: any, respond: (incoming: any) => void) => {
            called++;
            assert.equal(target.href, start.href); assert.equal(options.agent, false); assert.equal(options.method, 'GET');
            assert.equal(options.servername, 'api.example.test'); assert.equal(options.rejectUnauthorized, true);
            assert.equal(options.family, 4); assert.equal(options.autoSelectFamily, false); assert.equal(options.maxHeaderSize, 8192);
            assert.deepEqual(options.headers, { Accept: 'application/json', 'Accept-Encoding': 'identity', 'User-Agent': 'Finitude/1.0 ( lookup-operator@example.test )' });
            for (const forbidden of ['Cookie', 'Authorization', 'Referer']) assert.equal(forbidden in options.headers, false);
            options.lookup('other.example.test', { all: false }, (error: unknown, ip: string, family: number) => {
                assert.equal(error, null); assert.equal(ip, '8.8.8.8'); assert.equal(family, 4);
            });
            options.lookup('other.example.test', { all: true }, (error: unknown, answers: unknown) => {
                assert.equal(error, null); assert.deepEqual(answers, [address]);
            });
            const outgoing = new EventEmitter() as EventEmitter & { end: () => void };
            outgoing.end = () => respond(Object.assign(Readable.from([Buffer.from('{}')]), { statusCode: 200, headers: { 'content-type': 'application/json' }, rawHeaders: [] }));
            return outgoing;
        }) as NonNullable<PinnedHttpsTransport['httpsRequest']>
    });
    assert.equal(called, 1); assert.equal(url.href, start.href); assert.equal(opened.statusCode, 200);
    opened.body.destroy();
});

test('a refused redirect destination fails before a second DNS lookup or connection and destroys the redirect body', async () => {
    const lookups: string[] = [], hops: number[] = [];
    let requests = 0; const body = Readable.from([Buffer.from('moved')]);
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy({
        destination: (url, hop) => { hops.push(hop); return url.hostname === 'api.example.test' ? url : null; }
    }), {
        lookup: async hostname => { lookups.push(hostname); return [address]; },
        request: async () => { requests++; return { ...response(302, { location: 'https://elsewhere.example.test/next' }), body }; }
    }), /SYNTHETIC_PINNED_FAILURE/);
    assert.deepEqual(lookups, ['api.example.test']); assert.equal(requests, 1); assert.equal(body.destroyed, true);
    assert.deepEqual(hops, [0, 1]);
});

test('destinations see hops 0..n, more than three redirects fail and loops fail', async () => {
    const hops: number[] = [];
    let requests = 0;
    const { url } = await openPinnedHttps(start, new AbortController().signal, policy({ destination: (target, hop) => { hops.push(hop); return target; } }), {
        lookup: async () => [address],
        request: async () => { requests++; return requests <= 3 ? response(301, { location: `/hop-${requests}` }) : response(200, {}, '{}'); }
    });
    assert.equal(url.pathname, '/hop-3'); assert.deepEqual(hops, [0, 1, 2, 3]);
    requests = 0;
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address], request: async () => { requests++; return response(307, { location: `/again-${requests}` }); }
    }));
    assert.equal(requests, 4);
    requests = 0;
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address], request: async () => { requests++; return response(308, { location: 'https://API.example.test/start' }); }
    }));
    assert.equal(requests, 1);
    requests = 0;
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy({ maximumRedirects: 99 }), {
        lookup: async () => [address], request: async () => { requests++; return response(302, { location: `/clamped-${requests}` }); }
    }));
    assert.equal(requests, 4, 'maximumRedirects is clamped to three');
});

test('a duplicate, missing or unsafe Location fails on the first hop', async () => {
    for (const raw of [['Location', '/a', 'location', '/b'], [], ['Location', '/bad\nvalue']]) {
        let requests = 0;
        await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
            lookup: async () => [address],
            request: async () => { requests++; return { statusCode: 302, headers: raw.length ? { location: raw[1] } : {}, rawHeaders: raw, body: Readable.from([]) }; }
        }));
        assert.equal(requests, 1);
    }
});

test('declared and streamed byte caps hold and an empty or truncated body fails', async () => {
    const signal = new AbortController().signal;
    assert.equal((await readPinnedBody(response(200, { 'content-length': '2' }, '{}'), signal, 2, failure)).toString(), '{}');
    for (const candidate of [response(200, { 'content-length': '5' }, '{}   '), response(200, {}, 'x'.repeat(5)), response(200, {}, ''),
        response(200, { 'content-length': '10' }, '{}'), response(200, { 'content-length': '0' }, ''), response(200, { 'content-length': '-1' }, '{}')]) {
        await assert.rejects(readPinnedBody(candidate, signal, 4, failure), /SYNTHETIC_PINNED_FAILURE/);
    }
});

test('a stalled DNS lookup and a stalled body both end at the one shared deadline', async () => {
    const keepAlive = setTimeout(() => undefined, 2000);
    try {
        let started = Date.now();
        await assert.rejects(openPinnedHttps(start, AbortSignal.timeout(30), policy(), { lookup: () => new Promise(() => undefined) }), /SYNTHETIC_PINNED_FAILURE/);
        assert.ok(Date.now() - started < 1000);
        const deadline = AbortSignal.timeout(40);
        let sent = false;
        const body = new Readable({ read() { if (!sent) { sent = true; this.push(Buffer.from('{')); } } });
        const { response: opened } = await openPinnedHttps(start, deadline, policy(), {
            lookup: async () => [address], request: async () => ({ statusCode: 200, headers: {}, body })
        });
        started = Date.now();
        await assert.rejects(readPinnedBody(opened, deadline, 1024, failure), /SYNTHETIC_PINNED_FAILURE/);
        assert.ok(Date.now() - started < 1000); assert.equal(body.destroyed, true);
    } finally { clearTimeout(keepAlive); }
});

test('strictHttpsUrl applies the legacy artwork URL rules', () => {
    for (const value of ['https://musicbrainz.org/ws/2/release', 'https://archive.org:443/download/x', 'https://dn1.ca.archive.org/0/items/x']) {
        assert.equal(strictHttpsUrl(value)?.href, new URL(value).href);
    }
    for (const value of [null, 42, '', 'http://musicbrainz.org/', 'https://user:pass@musicbrainz.org/', 'https://musicbrainz.org:8443/',
        'https://musicbrainz.org/#fragment', 'https://127.0.0.1/', 'https://[::1]/', 'https://localhost/', 'https://musicbrainz.org./',
        'https://musicbrainz.org/a b', 'https://musicbrainz.org/a\\b', `https://musicbrainz.org/${'x'.repeat(2048)}`]) {
        assert.equal(strictHttpsUrl(value), null, String(value));
        assert.equal(legacyCatalogArtworkUrl(value), null, String(value));
    }
});

/** Replaces the promise resolver's queries (already refused by the guard) for one test and restores them. */
const stubResolver = (resolve4: () => Promise<string[]>, resolve6: () => Promise<string[]>, onCancel: () => void = () => undefined) => {
    const prototype = dnsPromises.Resolver.prototype as unknown as Record<string, unknown>;
    const saved = { resolve4: prototype.resolve4, resolve6: prototype.resolve6 };
    const calls = { queries: 0, cancels: 0 };
    prototype.resolve4 = () => { calls.queries++; return resolve4(); };
    prototype.resolve6 = () => { calls.queries++; return resolve6(); };
    // `cancel` is inherited from the resolver base class; an own property shadows it until restore.
    prototype.cancel = () => { calls.cancels++; onCancel(); };
    return { calls, restore: () => { Object.assign(prototype, saved); delete prototype.cancel; } };
};
const dnsError = (code: string) => Object.assign(new Error(`query ${code} api.example.test`), { code });
const noConnection = (() => assert.fail('no connection is opened')) as unknown as NonNullable<PinnedHttpsTransport['httpsRequest']>;

test('the production resolver keeps both families, tolerates missing records and fails on any other DNS error', async () => {
    const signal = new AbortController().signal;
    const cases: [() => Promise<string[]>, () => Promise<string[]>, LookupAddress[] | null][] = [
        [async () => ['8.8.8.8', '1.1.1.1'], async () => { throw dnsError('ENODATA'); }, [address, { address: '1.1.1.1', family: 4 }]],
        [async () => { throw dnsError('ENOTFOUND'); }, async () => ['2606:4700:4700::1111'], [{ address: '2606:4700:4700::1111', family: 6 }]],
        [async () => ['8.8.8.8'], async () => ['2606:4700:4700::1111'], [address, { address: '2606:4700:4700::1111', family: 6 }]],
        [async () => { throw dnsError('ENOTFOUND'); }, async () => { throw dnsError('ENODATA'); }, []],
        [async () => { throw dnsError('ESERVFAIL'); }, async () => ['2606:4700:4700::1111'], null],
        [async () => ['8.8.8.8'], async () => { throw dnsError('ETIMEOUT'); }, null],
        [async () => { throw new Error('no code'); }, async () => [], null]
    ];
    for (const [resolve4, resolve6, expected] of cases) {
        const stub = stubResolver(resolve4, resolve6);
        try {
            if (expected) assert.deepEqual(await lookupPublicAddresses('api.example.test', signal), expected);
            else await assert.rejects(lookupPublicAddresses('api.example.test', signal), /ADMIN_PINNED_HTTPS_FAILED/);
            assert.equal(stub.calls.queries, 2); assert.ok(stub.calls.cancels >= 1, 'the per-request resolver is always cancelled');
        } finally { stub.restore(); }
    }
});

test('the production resolver is cancelled on abort, never queries after one, and its answers are policed like any other', async () => {
    let rejectPending: (error: Error) => void = () => undefined;
    const stub = stubResolver(() => new Promise((_resolve, reject) => { rejectPending = reject; }), async () => [], () => rejectPending(dnsError('ECANCELLED')));
    try {
        const controller = new AbortController();
        const pending = lookupPublicAddresses('api.example.test', controller.signal);
        setTimeout(() => controller.abort(), 10);
        await assert.rejects(pending);
        assert.ok(stub.calls.cancels >= 1);
        const aborted = new AbortController(); aborted.abort();
        const before = stub.calls.queries;
        await assert.rejects(lookupPublicAddresses('api.example.test', aborted.signal));
        assert.equal(stub.calls.queries, before, 'a pre-aborted lookup sends no query');
    } finally { stub.restore(); }
    for (const [answers, label] of [[[], 'no answer'], [['10.0.0.1'], 'a private answer'], [['8.8.8.8', '192.168.1.1'], 'one private answer']] as const) {
        const answersStub = stubResolver(async () => [...answers], async () => { throw dnsError('ENODATA'); });
        try {
            await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), { httpsRequest: noConnection }), /SYNTHETIC_PINNED_FAILURE/, label);
        } finally { answersStub.restore(); }
    }
});

test('only the first public answer is pinned, and an IPv6 answer pins family 6 for both lookup forms', async () => {
    const ipv6: LookupAddress = { address: '2606:4700:4700::1111', family: 6 };
    const pinned: LookupAddress[] = [];
    const { response: opened } = await openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [ipv6, address], request: async (_target, chosen) => { pinned.push(chosen); return response(200, {}, '{}'); }
    });
    opened.body.destroy();
    assert.deepEqual(pinned, [ipv6]);
    let checked = false;
    const { response: viaHttps } = await openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [ipv6],
        httpsRequest: ((_target: URL, options: any, respond: (incoming: any) => void) => {
            assert.equal(options.family, 6);
            options.lookup('api.example.test', {}, (error: unknown, ip: string, family: number) => { assert.equal(error, null); assert.equal(ip, ipv6.address); assert.equal(family, 6); });
            options.lookup('api.example.test', { all: true }, (_error: unknown, answers: unknown) => { assert.deepEqual(answers, [ipv6]); checked = true; });
            const outgoing = new EventEmitter() as EventEmitter & { end: () => void };
            outgoing.end = () => respond(Object.assign(Readable.from([]), { statusCode: 204, headers: {}, rawHeaders: [] }));
            return outgoing;
        }) as NonNullable<PinnedHttpsTransport['httpsRequest']>
    });
    viaHttps.body.destroy();
    assert.equal(checked, true);
});

test('relative and protocol-relative Locations resolve against the current hop, 303 is followed and every redirect body is destroyed', async () => {
    const visited: string[] = [], bodies: Readable[] = [];
    const { url, response: final } = await openPinnedHttps(new URL('https://api.example.test/a/b'), new AbortController().signal, policy(), {
        lookup: async () => [address],
        request: async target => {
            visited.push(target.href);
            const next = visited.length === 1 ? response(303, { location: '../c?x=1' }, 'see other')
                : visited.length === 2 ? response(302, { location: '//other.example.test/d' }, 'found') : response(200, {}, '{}');
            bodies.push(next.body);
            return next;
        }
    });
    assert.deepEqual(visited, ['https://api.example.test/a/b', 'https://api.example.test/c?x=1', 'https://other.example.test/d']);
    assert.equal(url.href, 'https://other.example.test/d');
    assert.deepEqual(bodies.map(body => body.destroyed), [true, true, false], 'the caller owns the final body');
    final.body.destroy();
    let requests = 0;
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address], request: async () => { requests++; return response(301, { location: 'http://api.example.test/start' }); }
    }), /SYNTHETIC_PINNED_FAILURE/, 'a downgrade to http is refused by the strict URL policy');
    assert.equal(requests, 1);
});

test('a permissive policy cannot widen the strict HTTPS rules on hop 0 or on a redirect', async () => {
    const permissive = policy({ destination: url => url });
    for (const value of ['http://api.example.test/x', 'https://api.example.test:8443/x', 'https://10.0.0.1/x', 'https://[2606:4700:4700::1111]/x',
        'https://user:pass@api.example.test/x', 'https://api.example.test/x#fragment', 'https://localhost/x', 'https://api.example.test./x']) {
        let lookups = 0, requests = 0;
        await assert.rejects(openPinnedHttps(new URL(value), new AbortController().signal, permissive, {
            lookup: async () => { lookups++; return [address]; }, request: async () => { requests++; return response(200, {}, '{}'); }
        }), /SYNTHETIC_PINNED_FAILURE/, value);
        assert.deepEqual([lookups, requests], [0, 0], `${value} is refused before DNS`);
        lookups = 0; requests = 0;
        await assert.rejects(openPinnedHttps(start, new AbortController().signal, permissive, {
            lookup: async () => { lookups++; return [address]; },
            request: async () => { requests++; return requests === 1 ? response(302, { location: value }) : response(200, {}, '{}'); }
        }), /SYNTHETIC_PINNED_FAILURE/, `redirect to ${value}`);
        assert.deepEqual([lookups, requests], [1, 1], `a redirect to ${value} is refused before a second lookup`);
    }
});

test('a pre-aborted signal, a transport error and a failed outgoing request all become the policy failure', async () => {
    const isPolicyFailure = (error: unknown) => error instanceof Error && error.message === 'SYNTHETIC_PINNED_FAILURE';
    const aborted = new AbortController(); aborted.abort();
    let lookups = 0;
    await assert.rejects(openPinnedHttps(start, aborted.signal, policy(), { lookup: async () => { lookups++; return [address]; } }), isPolicyFailure);
    assert.equal(lookups, 0, 'nothing is resolved after the deadline');
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address], request: async () => { throw new Error(`ECONNRESET ${start.href}`); }
    }), isPolicyFailure);
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), { lookup: async () => { throw new Error('resolver crashed'); } }), isPolicyFailure);
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy(), {
        lookup: async () => [address],
        httpsRequest: (() => {
            const outgoing = new EventEmitter() as EventEmitter & { end: () => void; once: EventEmitter['once'] };
            outgoing.end = () => process.nextTick(() => outgoing.emit('error', new Error('unable to verify the first certificate')));
            return outgoing;
        }) as unknown as NonNullable<PinnedHttpsTransport['httpsRequest']>
    }), isPolicyFailure);
    await assert.rejects(openPinnedHttps(start, new AbortController().signal, policy({ destination: () => null }), { lookup: async () => { lookups++; return [address]; } }), isPolicyFailure);
    assert.equal(lookups, 0, 'a refused first destination is never resolved');
});
